from assignment_second_half_common import *
qs=[]
proj=F('x=f X/Z; y=f Y/Z; d=sqrt((x_A-x_B)^2+(y_A-y_B)^2)',{'x':('horizontal image coordinate','mm'),'y':('vertical image coordinate','mm'),'f':('focal length','mm'),'X':('camera-frame horizontal coordinate','m'),'Y':('camera-frame vertical coordinate','m'),'Z':('positive camera-frame depth','m'),'d':('image-plane Euclidean separation','mm'),'x_A':('image horizontal coordinate of A','mm'),'x_B':('image horizontal coordinate of B','mm'),'y_A':('image vertical coordinate of A','mm'),'y_B':('image vertical coordinate of B','mm')},['Ideal pinhole model; common image plane and camera coordinates; Z>0.'])
qs.append(Q(7,1,1,'Camera-frame projection','For the assignment’s points A=(1,0,2) m and B=(1,0,4) m, explicitly assume the stated world frame coincides with the camera frame. With f=20 mm and x=fX/Z, y=fY/Z, what is their image-plane separation?', ['5 mm','10 mm','15 mm','2 mm'],['The image positions are (10,0) and (5,0) mm, giving 5 mm separation.','10 mm is A’s image coordinate, not the separation.','15 mm adds the two positive coordinates instead of subtracting them.','2 m is the world-depth difference; copying its numeral into millimetres is not image projection.'],[C(29,'Week 7 Q1, world-coordinate premise and projection working','A=(1,0,2)m, B=(1,0,4)m, f=20 mm; x=fX/Z, y=fY/Z.','equation','conflict')],'The 5 mm result is valid with the added world-to-camera alignment assumption; the original does not specify camera extrinsics.',assumptions=['World and camera frames coincide; ideal pinhole projection; the same principal-point offset would cancel in the separation.'],steps=['X/Z is dimensionless: 1/2 and 1/4.','A projects to (20/2,0)=(10,0) mm; B projects to (20/4,0)=(5,0) mm.','Euclidean separation is |10−5|=5 mm.'],formulas=[proj],qtype='numerical',conflict={'issue':'The original supplies world coordinates without camera extrinsics.','resolution':'The adaptation explicitly identifies world and camera frames before using the source formula.','method':'Apply the printed pinhole equation only after supplying the missing frame premise.'},angles=['projection_working','frame_assumption','units']))
qs.append(Q(7,2,2,'Perspective scale','Two frontoparallel squares have equal physical side length H and positive camera depths Z and 2Z. In the same ideal pinhole camera, how do their image side lengths compare?', ['The farther square has half the image side length.','The farther square has the same image side length.','The farther square has twice the image side length.','The farther square has one quarter of the image side length.'],['Image side length fH/Z scales inversely with depth, so doubling depth halves length.','Equal image size would be an orthographic-style depth-independent result, not this perspective model.','This reverses the inverse-depth relation.','One quarter applies to projected area when both side lengths halve, not to a side length.'],[C(29,'Week 7 Q2, equal cube faces at different depths','The back face (farther) of the cube appears smaller compared to the front face (nearest).')],'Equal-size frontoparallel objects become smaller in proportion to inverse depth; this is not a claim about differently sized objects.',assumptions=['Same physical H, orientation and focal length; no distortion; Z>0.'],formulas=[F('h=fH/Z; h(2Z)/h(Z)=1/2',{'h':('image side length','mm'),'f':('focal length','mm'),'H':('physical side length','m'),'Z':('camera depth','m')},['Frontoparallel square and ideal pinhole camera.'])],angles=['perspective_scale','equal_size_assumption','length_vs_area']))
qs.append(Q(7,3,3,'Unsigned image overflow','A NumPy array is created as I=np.array([230], dtype=np.uint8). Compare a uint8 addition of 50 with an explicit float conversion before addition. What values result from (I+np.uint8(50))[0] and (I.astype(float)+50)[0], respectively?', ['24 and 280.0','255 and 280.0','24 and 24.0','280 and 280.0'],['The uint8 result wraps modulo 256; conversion before addition preserves the real-valued sum.','255 is saturation, not the stated modular uint8 array addition.','Casting before addition avoids the wrap; casting the already-wrapped result would give 24.0.','280 cannot be represented by uint8; the first addition retains that dtype.'],[C(29,'Week 7 Q3, uint8 value and addition premise','uint8 image I contains a pixel with value 230; O=I+50.','code'),C(30,'Week 7 Q3 continuation, modular working and conversion note','230+50=280; 280 mod 256=24; conversion from uint8 to floating point is important.','equation')],'The arithmetic path, not merely the displayed output type, determines whether overflow is retained.',assumptions=['One-element uint8 array; both addends of the first operation are uint8; float conversion occurs before the second addition.'],steps=['Unsigned 8-bit integers have 256 residue values, 0 through 255.','230+50=280, and 280−256=24.','Converting 230 to float before adding yields 280.0, without uint8 overflow.'],formulas=[F('u=(a+b) mod 256',{'u':('uint8 result','dimensionless intensity code'),'a':('input intensity code','dimensionless'),'b':('added intensity code','dimensionless')},['Unsigned 8-bit modular addition.'])],qtype='algorithm_trace',angles=['uint8_overflow','cast_timing','saturation_distinction']))
qs.append(Q(7,4,4,'Correlation and convolution','At one centered valid window, I=[[1,2,3],[4,5,6],[7,8,9]] and K=[[1,2,0],[0,−1,1],[2,0,−2]]. Define correlation by direct elementwise products and convolution by rotating K by 180° first. What are the two sums, in that order?', ['2 and 28','28 and 2','2 and −28','−2 and 28'],['Direct products total 2; the rotated-kernel products total 28.','This exchanges the operations’ kernel conventions.','The convolution is positive 28; a rotation does not negate the sum.','The direct sum is positive 2; this changes the correlation sign.'],[C(30,'Week 7 Q4, printed I/K matrices and two worked product sums','I=[[1,2,3],[4,5,6],[7,8,9]], K=[[1,2,0],[0,−1,1],[2,0,−2]]; K_flip=[[-2,0,2],[1,-1,0],[0,2,1]].','equation')],'An asymmetric kernel distinguishes correlation from convolution because a 180° rotation changes its arrangement.',steps=['Correlation: 1+4+0+0−5+6+14+0−18=2.','Rotate both kernel axes: [[−2,0,2],[1,−1,0],[0,2,1]].','Convolution: −2+0+6+4−5+0+0+16+9=28.'],formulas=[F('R=sum_i sum_j I[i,j]K[i,j]; V=sum_i sum_j I[i,j]K[2−i,2−j]',{'R':('correlation sum','arbitrary response units'),'V':('convolution sum','arbitrary response units'),'I':('3×3 image sample array','arbitrary intensity units'),'K':('3×3 kernel array','dimensionless'),'i':('zero-based row index 0..2','dimensionless'),'j':('zero-based column index 0..2','dimensionless')},['One valid window; no boundary padding or normalization.'])],qtype='numerical',difficulty='medium',angles=['matrix_transcription','kernel_flip','signed_working']))
qs.append(Q(7,5,5,'Circularity and shape inference','Using corrected area units, a region has A=100 pixel² and perimeter P=40 pixels. Which statement correctly combines circularity ρ=4πA/P² with the strength of shape inference?', ['ρ=π/4≈0.785; an ideal square matches, but this scalar alone does not uniquely identify an arbitrary shape.','ρ=1; the region must be a perfect circle.','ρ=π/4≈0.785; every region with this value must be a square.','ρ=π≈3.142; the region is more circular than an ideal circle.'],['The computed value equals a square’s circularity, while area and perimeter alone do not encode the full boundary.','The calculation is π/4, not 1; a circle at that area has a different perimeter.','The numerical value is right, but a single shape descriptor is not a unique shape identifier.','This fails to square the full perimeter or otherwise mis-scales the ratio; the given formula yields π/4.'],[C(30,'Week 7 Q5, area and perimeter premise','Area=100 pixels; Perimeter=40 pixels.','statement','conflict'),C(31,'Week 7 Q5 continuation, circularity and closest-choice qualification','ρ=4π(100)/40²=π/4≈0.785; closest to a square among the given choices.','equation')],'The adaptation uses pixel² for area and retains the original explanation’s closest-choice limitation instead of claiming unique identification.',assumptions=['Ideal continuous-shape formula applied to supplied area/perimeter; digital boundary estimation effects are outside this example.'],steps=['P²=1600 pixel².','ρ=400π/1600=π/4≈0.785.','An ideal square has A=s² and P=4s, hence the same ratio; matching the ratio does not reconstruct a unique contour.'],formulas=[F('ρ=4πA/P²',{'ρ':('circularity','dimensionless'),'A':('region area','pixel²'),'P':('region perimeter','pixels')},['Area and perimeter expressed in compatible units.'])],qtype='numerical',conflict={'issue':'The source labels area in pixels rather than square pixels.','resolution':'The adaptation explicitly uses pixel² and preserves the closest-choice, nonunique interpretation.','method':'Dimensional check of the printed circularity ratio.'},angles=['circularity_working','area_units','nonunique_descriptor']))
qs.append(Q(7,6,6,'Structure tensor classification','On a common structure-tensor scale, P has eigenvalues (0.01,0.02), Q has (0.01,5.00), and R has (4.50,5.20). Treat values near 0.01 as small and values near 5 as large. Which classification is consistent with local intensity variation?', ['P: flat; Q: edge; R: corner.','P: corner; Q: edge; R: flat.','P: flat; Q: corner; R: edge.','P: edge; Q: flat; R: corner.'],['Both small means weak variation; one large means directional variation; both large means variation in both principal directions.','This reverses the meanings of two-small and two-large eigenvalues.','One large eigenvalue indicates an edge rather than a corner; two large values indicate a corner.','P has no large direction; Q has one strong direction and is not flat.'],[C(31,'Week 7 Q6, eigenvalue table rows P/Q/R and corner explanation','P:(0.01,0.02); Q:(0.01,5.00); R:(4.50,5.20). In R both eigenvalues are large → corner.','table')],'A corner needs appreciable variation in both principal directions, not merely a large maximum eigenvalue.',assumptions=['Same image normalization, window and tensor scale for all three locations.'],angles=['all_table_rows','corner_edge_flat','shared_scale']))
qs.append(Q(7,7,7,'Training dependencies','For one gradient-descent training step on a fixed batch, no current predictions or gradients have been computed. Which order respects the dependencies among the four operations?', ['Forward prediction → loss evaluation → backpropagation of gradients → parameter update.','Forward prediction → parameter update → loss evaluation → backpropagation of gradients.','Backpropagation of gradients → forward prediction → loss evaluation → parameter update.','Loss evaluation → forward prediction → backpropagation of gradients → parameter update.'],['The current loss needs predictions, gradients need that loss/computation graph, and the update uses those gradients.','This updates parameters before obtaining the current loss gradient.','This attempts current-batch backpropagation before constructing its forward computation.','The prediction-dependent loss cannot be evaluated before current predictions exist.'],[C(31,'Week 7 Q7, four training-cycle options','Forward pass → Loss calculation → Backpropagation → Gradient descent.'),C(32,'Week 7 Q7 continuation, explanation of stage roles','Prediction through forward propagation, loss evaluation, gradient calculation through backpropagation, and parameter update using gradient descent.')],'Backpropagation computes gradients; gradient descent uses them to change parameters.',assumptions=['Standard supervised gradient-descent step; no reused stale gradients or pipelined asynchronous update.'],steps=['Compute the batch predictions.','Evaluate prediction-dependent loss.','Backpropagate to obtain current parameter gradients.','Apply the gradient-descent update.'],qtype='algorithm_trace',angles=['training_order','backprop_vs_update']))
qs.append(Q(7,8,8,'Bias versus threshold convention','For x=(2,3), w=(0.5,−1) and b=1, compare two explicitly defined nets: z_add=w·x+b and z_threshold=w·x−b. Both use y=1 when z≥0 and y=0 otherwise. Which pair (z_add,y_add; z_threshold,y_threshold) is correct?', ['(−1,0; −3,0)','(−3,0; −1,0)','(−1,1; −3,1)','(1,1; 3,1)'],['The dot product is −2; adding b gives −1 and subtracting b gives −3, both below zero.','This swaps the additive-bias and subtractive-threshold definitions.','Both nets are negative, so neither activates the stated step function.','This reverses the sign of the weighted input and does not follow either explicit definition.'],[C(32,'Week 7 Q8, b=1 premise, step rule and w0=−b explanation','x1=2, x2=3, w1=0.5, w2=−1, b=1; output 1 if weighted sum≥0; explanation sets x0=1 and w0=−b.','equation','conflict')],'The source’s subtractive-threshold calculation and an additive-bias convention produce different nets but the same output here. The adaptation makes both conventions explicit.',steps=['w·x=0.5×2−1×3=−2.','z_add=−2+1=−1 and z_threshold=−2−1=−3.','Both values are negative, hence both step outputs are 0.'],formulas=[F('z_add=w·x+b; z_threshold=w·x−b; y=1 if z≥0 else 0',{'z_add':('additive-bias net','dimensionless'),'z_threshold':('subtractive-threshold net','dimensionless'),'w':('weight vector','dimensionless'),'x':('input vector','dimensionless'),'b':('specified bias or threshold parameter','dimensionless'),'z':('net supplied to step activation','dimensionless'),'y':('binary output','dimensionless')},['The two conventions are separately defined rather than silently interchanged.'])],qtype='numerical',conflict={'issue':'The source calls b a bias but its working uses w0=−b.','resolution':'Both additive-bias and subtractive-threshold nets are explicitly compared without changing the original record.','method':'Evaluate each stated affine expression and then apply the same printed step rule.'},angles=['bias_convention','weighted_sum','step_output']))
qs.append(Q(7,9,9,'Convolution shape inversion','A 28×28×1 input passes through 16 square convolution filters with stride 1, zero padding and dilation 1. The output spatial size is 24×24. What are the kernel spatial size and full output shape?', ['5×5; 24×24×16','4×4; 24×24×16','5×5; 24×24×1','16×16; 24×24×5'],['24=28−K+1 gives K=5; each of 16 filters produces one output channel.','K=4 would produce 25×25 at these stride/padding settings.','The spatial kernel is right, but output channels count filters, not input channels.','This confuses number of filters with kernel width; K=16 would give 13×13 spatial output.'],[C(32,'Week 7 Q9, convolution dimensions and worked output','Input 28×28×1; stride 1; padding 0; 16 kernels; output spatial dimensions 24×24; K=5 and output 24×24×16.','equation')],'Spatial size is determined by kernel geometry, stride and padding; channel count is determined by the number of filters.',assumptions=['Standard valid convolution with unit dilation; channel-last shape notation.'],steps=['Use O=floor((I+2P−K)/S)+1 with I=28,P=0,S=1.','24=28−K+1, so K=5.','Sixteen filters give sixteen output channels: 24×24×16.'],formulas=[F('O=floor((I+2P−K)/S)+1; C_out=N_filters',{'O':('output side length','pixels'),'I':('input side length','pixels'),'P':('padding per side','pixels'),'K':('kernel side length','pixels'),'S':('stride','pixels'),'C_out':('output channel count','channels'),'N_filters':('number of filters','filters')},['Dilation 1; square input/kernel; independent output channel per filter.'])],qtype='numerical',angles=['inverse_shape','filter_count_vs_size']))
qs.append(Q(7,10,10,'Anchor-free head distinction','In the assignment’s YOLOv8-versus-YOLOv5 comparison, what does the change to an anchor-free detection head remove the need to predefine?', ['A set of anchor-box shapes used as detection priors.','Every spatial prediction location on the feature maps.','The input image’s pixel-coordinate system.','The separate object-class labels learned by the detector.'],['The contrast concerns predefined anchor-box templates, not the absence of locations or classes.','Anchor-free heads still predict at spatial locations; locations and anchor-box shapes are different ideas.','Predicted boxes still need coordinates in an image or corresponding feature representation.','The detector still predicts classes; anchor freedom is not class-free learning.'],[C(33,'Week 7 Q10, highlighted comparison option B','YOLOv8 uses an anchor-free detection head, reducing the need for predefined anchor boxes.')],'Anchor-free refers to avoiding predefined box priors, not eliminating spatial prediction or object classification.',assumptions=['Interpret the particular YOLOv8/YOLOv5 architecture comparison printed in this course, not all model variants or current runtime behavior.'],angles=['anchor_box_prior','anchor_points_distinction']))
notes=[(29,'1','Viewed Q1 world-coordinate wording and printed 5 mm working, Q2 cube-depth prose and highlighted B, Q3 uint8 prompt. Q1 omits extrinsics; Q2 size comparison needs equal physical size.'),(30,'2','Viewed Q3 modular equation and float-conversion note; every I/K/K_flip entry and both product sums in Q4; Q5 area/perimeter and first option. Area is literally printed as pixels, not pixel².'),(31,'3','Viewed Q5 highlighted square and closest-given-choice qualification; Q6 all eigenvalue-table cells and highlight R; Q7 all four training sequences and highlighted B.'),(32,'4','Viewed Q7 stage-role explanation; Q8 b=1, threshold rule, highlighted 0 and explicit w0=−b working; Q9 dimensions, all options, shape formula and full 24×24×16 output.'),(33,'5','Viewed Q10 all four options, highlighted anchor-free statement, lecture-reference line and END. No additional technical diagram or code block appears.')]

q=qs[1]
q['stem']='Two frontoparallel squares have equal physical side length H and depths Z and 2Z. Separately, two distinct parallel straight lines lie in one plane at fixed camera depth Z0>0, parallel to the image plane. In an ideal pinhole camera, which paired conclusion is correct?'
texts=['The farther square has half the image side length; the two lines remain parallel in the image.','The farther square has half the image side length; the two lines meet at a finite image vanishing point.','The squares have equal image side lengths; the two lines remain parallel in the image.','The farther square has one quarter of the image side length; the two lines remain parallel in the image.']
reasons=['Inverse depth halves side length, while projection at common fixed depth is a uniform scale that preserves these parallel lines.','The size conclusion is right, but lines parallel to the image plane have no finite vanishing point.','The parallel-line conclusion is right, but equal physical size at different depths does not imply equal image size.','One quarter is the projected area ratio, not the image side-length ratio.']
for o in q['options']:o['text']=texts[int(o['id'][1:])-1]
q['solution']['optionExplanations']={f'o{i+1}':r for i,r in enumerate(reasons)}
q['solution']['justification']='Perspective size varies inversely with depth. The source explanation overgeneralizes parallel-line convergence: lines parallel to the image plane remain parallel, so the finite vanishing-point claim requires a direction with nonzero depth component.'
q['solution']['simpleExplanation']=q['solution']['justification'];q['solution']['misconceptions']=reasons[1:]
q['solution']['steps']=['For the squares, h(2Z)=fH/(2Z)=h(Z)/2.','For the lines at Z0, each point maps by (X,Y) → (fX/Z0,fY/Z0), a uniform scaling of their common plane.','Uniform scaling preserves their parallel directions and distinct offsets.']
q['solution']['formulas'].append(F('(x,y)=(fX/Z0,fY/Z0)',{'x':('horizontal image coordinate','mm'),'y':('vertical image coordinate','mm'),'f':('focal length','mm'),'X':('camera-frame horizontal coordinate','m'),'Y':('camera-frame vertical coordinate','m'),'Z0':('common fixed positive depth of both lines','m')},['Both lines lie in a common plane parallel to the image plane.']))
q['citations']=[C(29,'Week 7 Q2 explanation, parallel-edge convergence and nearer/farther cube faces','Parallel edges in the world are projected as lines that converge toward a vanishing point; the farther cube face appears smaller.','statement','conflict'),C(29,'Week 7 Q1 explanation, pinhole equations','x=fX/Z and y=fY/Z.','equation')]
q['conflictResolution']={'status':'qualification_pending_independent_review','questionVersion':1,'sourceId':'assignments','sourceSha256':SOURCE,'physicalPage':29,'sourceClaim':'Q2 explanation does not exclude world-parallel lines parallel to the image plane from its finite convergence statement.','basis':'The adaptation supplies fixed common depth and applies the printed pinhole model, exposing the parallel-image-line exception.','method':'Substitute Z=Z0 into the source projection equations; the mapping is uniform planar scaling.'}
q['testedAssignmentAngles']+=['parallel_image_plane_exception']
qs[2]['externalSources']=[{'title':'NumPy 2.3 manual: Data types, array conversion and overflow','url':'https://numpy.org/doc/2.3/user/basics.types.html','version':'NumPy 2.3 documentation; author runtime NumPy 2.3.5','accessedAt':NOW(),'support':'Explicit uint8 arrays, astype conversion and fixed-width integer overflow. Exact two expressions checked in the permitted default runtime.'}]
save_week(7,qs,notes)

